"use strict";(globalThis.webpackChunkpython_from_zero_to_hero=globalThis.webpackChunkpython_from_zero_to_hero||[]).push([[207],{2242(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"courseSidebar":[{"type":"link","label":"Welcome","href":"/python-from-zero-to-hero/docs/","docId":"intro","unlisted":false},{"type":"category","label":"Beginner","collapsed":false,"items":[{"type":"link","label":"Beginner","href":"/python-from-zero-to-hero/docs/beginner/","docId":"beginner/index","unlisted":false},{"type":"link","label":"Variables & Types","href":"/python-from-zero-to-hero/docs/beginner/variables-types","docId":"beginner/variables-types","unlisted":false},{"type":"link","label":"Input, Output & Strings","href":"/python-from-zero-to-hero/docs/beginner/io-strings","docId":"beginner/io-strings","unlisted":false},{"type":"link","label":"Loops & Iteration","href":"/python-from-zero-to-hero/docs/beginner/loops","docId":"beginner/loops","unlisted":false},{"type":"link","label":"Lists & Tuples","href":"/python-from-zero-to-hero/docs/beginner/lists-tuples","docId":"beginner/lists-tuples","unlisted":false},{"type":"link","label":"Functions","href":"/python-from-zero-to-hero/docs/beginner/functions","docId":"beginner/functions","unlisted":false},{"type":"link","label":"Dicts, Sets & Comprehensions","href":"/python-from-zero-to-hero/docs/beginner/dicts-sets","docId":"beginner/dicts-sets","unlisted":false}],"collapsible":true},{"type":"category","label":"Intermediate","collapsed":true,"items":[{"type":"link","label":"Intermediate","href":"/python-from-zero-to-hero/docs/intermediate/","docId":"intermediate/index","unlisted":false},{"type":"link","label":"File I/O","href":"/python-from-zero-to-hero/docs/intermediate/file-io","docId":"intermediate/file-io","unlisted":false},{"type":"link","label":"Exceptions & Error Handling","href":"/python-from-zero-to-hero/docs/intermediate/exceptions","docId":"intermediate/exceptions","unlisted":false},{"type":"link","label":"Classes & Objects","href":"/python-from-zero-to-hero/docs/intermediate/classes-objects","docId":"intermediate/classes-objects","unlisted":false},{"type":"link","label":"Inheritance & Dunder Methods","href":"/python-from-zero-to-hero/docs/intermediate/inheritance","docId":"intermediate/inheritance","unlisted":false},{"type":"link","label":"Design Patterns","href":"/python-from-zero-to-hero/docs/intermediate/design-patterns","docId":"intermediate/design-patterns","unlisted":false}],"collapsible":true},{"type":"category","label":"Advanced","collapsed":true,"items":[{"type":"link","label":"Advanced","href":"/python-from-zero-to-hero/docs/advanced/","docId":"advanced/index","unlisted":false},{"type":"link","label":"Decorators & Generators","href":"/python-from-zero-to-hero/docs/advanced/decorators-generators","docId":"advanced/decorators-generators","unlisted":false},{"type":"link","label":"Async & Context Managers","href":"/python-from-zero-to-hero/docs/advanced/async-context-managers","docId":"advanced/async-context-managers","unlisted":false},{"type":"link","label":"REST APIs & HTTP","href":"/python-from-zero-to-hero/docs/advanced/rest-apis","docId":"advanced/rest-apis","unlisted":false},{"type":"link","label":"Databases & SQLite","href":"/python-from-zero-to-hero/docs/advanced/databases","docId":"advanced/databases","unlisted":false},{"type":"link","label":"Web Scraping & CLI","href":"/python-from-zero-to-hero/docs/advanced/scraping-cli","docId":"advanced/scraping-cli","unlisted":false}],"collapsible":true}]},"docs":{"advanced/async-context-managers":{"id":"advanced/async-context-managers","title":"Async Programming & Context Managers","description":"In this module you will learn how Python handles asynchronous programming with async/await and asyncio, how to build and use context managers with the with statement, and how to add type annotations to make your code self-documenting. By the end you will be able to write concurrent async programs, create custom context managers, and annotate function signatures.","sidebar":"courseSidebar"},"advanced/databases":{"id":"advanced/databases","title":"Databases & SQLite","description":"In this module you will learn how to store and query structured data using SQL and Python\'s built-in sqlite3 module. You will write CREATE TABLE, INSERT, SELECT, UPDATE, and DELETE statements, use parameterized queries to prevent SQL injection, and perform JOIN and aggregation queries. Because sqlite3 is natively available in Pyodide, all exercises run directly in the browser using in-memory databases.","sidebar":"courseSidebar"},"advanced/decorators-generators":{"id":"advanced/decorators-generators","title":"Decorators & Generators","description":"In this module you will master two of Python\'s most powerful features: decorators that wrap and enhance functions without modifying them, and generators that produce values lazily for memory-efficient iteration. By the end you will be able to write reusable decorators, create infinite sequences with yield, and use itertools to compose pipelines.","sidebar":"courseSidebar"},"advanced/index":{"id":"advanced/index","title":"Advanced","description":"This section covers advanced Python topics for developers ready to master the language.","sidebar":"courseSidebar"},"advanced/rest-apis":{"id":"advanced/rest-apis","title":"REST APIs & HTTP","description":"In this module you will learn how web applications communicate over HTTP, how to work with JSON data, how to use the requests library patterns for GET, POST, PUT, and DELETE operations, and how to handle API authentication and errors. Because real HTTP calls don\'t work inside the browser sandbox, the exercises use a mock requests object that behaves identically to the real library \u2014 so you learn the exact same patterns you\'d use in production.","sidebar":"courseSidebar"},"advanced/scraping-cli":{"id":"advanced/scraping-cli","title":"Web Scraping & CLI Tools","description":"In this module you will learn web scraping patterns \u2014 extracting structured data from HTML \u2014 and how to build command-line interface (CLI) tools with Python\'s argparse module. Because BeautifulSoup may not be available in the browser sandbox without micropip, the scraping exercises use mock HTML strings with regex and string methods (the same patterns you\'d apply to real HTML). For CLI exercises, you test argparse parsers using explicit argument lists.","sidebar":"courseSidebar"},"beginner/dicts-sets":{"id":"beginner/dicts-sets","title":"Dictionaries, Sets & Comprehensions","description":"Dictionaries and sets are Python\'s primary unordered collection types. Dictionaries map keys to values and are everywhere in real-world Python code. Sets store unique elements and support fast membership testing and mathematical set operations. In this module you will also master dict and set comprehensions for concise, expressive code.","sidebar":"courseSidebar"},"beginner/functions":{"id":"beginner/functions","title":"Functions","description":"Functions are the fundamental building blocks of reusable code. In this module you will learn to define functions with def, work with parameters and return values, use default arguments and flexible signatures with args/kwargs, write concise lambda functions, and understand variable scope. You will also learn to document your functions with docstrings*.","sidebar":"courseSidebar"},"beginner/index":{"id":"beginner/index","title":"Beginner","description":"This section covers Python fundamentals \u2014 the building blocks you need before tackling more complex topics.","sidebar":"courseSidebar"},"beginner/io-strings":{"id":"beginner/io-strings","title":"Input, Output & Strings","description":"In this module you will master Python\'s primary output tool \u2014 print() \u2014 and dive deep into strings: how to create them, transform them with methods, slice them, and format them for display. By the end you will be able to manipulate text fluently and produce well-formatted output.","sidebar":"courseSidebar"},"beginner/lists-tuples":{"id":"beginner/lists-tuples","title":"Lists & Tuples","description":"Lists and tuples are Python\'s two primary sequence types. Lists are mutable and packed with useful methods; tuples are immutable and ideal for fixed collections of values. In this module you will learn to create, index, slice, and transform both types, and discover the elegant power of list comprehensions.","sidebar":"courseSidebar"},"beginner/loops":{"id":"beginner/loops","title":"Loops & Iteration","description":"Loops let you repeat a block of code without copy-pasting it. In this module you will learn Python\'s two loop constructs \u2014 for and while \u2014 along with the tools that make iteration more expressive: range(), enumerate(), break, continue, and nested loops.","sidebar":"courseSidebar"},"beginner/variables-types":{"id":"beginner/variables-types","title":"Variables & Types","description":"In this module you will learn how Python stores data using variables, explore the four fundamental data types, convert between them, and format output with f-strings. By the end you will be comfortable declaring variables, reasoning about their types, and manipulating strings and numbers in Python.","sidebar":"courseSidebar"},"intermediate/classes-objects":{"id":"intermediate/classes-objects","title":"Classes & Objects","description":"In this module you will learn how Python implements Object-Oriented Programming (OOP) through classes, instances, and methods. You will define classes with init, manage instance and class variables, use self, and expose safe attribute access with @property. By the end you will be able to model real-world entities as Python classes.","sidebar":"courseSidebar"},"intermediate/design-patterns":{"id":"intermediate/design-patterns","title":"Design Patterns in Python","description":"In this module you will learn how classic design patterns are expressed in idiomatic Python. Patterns are proven, reusable solutions to recurring software design problems. Python\'s first-class functions, decorators, and dynamic typing often make patterns more concise than in other languages. By the end you will be able to recognise and apply Factory, Singleton, Observer, Strategy, and Iterator patterns in real code.","sidebar":"courseSidebar"},"intermediate/exceptions":{"id":"intermediate/exceptions","title":"Exceptions & Error Handling","description":"In this module you will learn how Python signals errors through exceptions, how to catch and handle them gracefully, how to raise your own exceptions, and how to build custom exception hierarchies. By the end you will be able to write robust programs that degrade gracefully instead of crashing unexpectedly.","sidebar":"courseSidebar"},"intermediate/file-io":{"id":"intermediate/file-io","title":"File I/O","description":"In this module you will learn how Python reads and writes files using the built-in open() function, handles CSV and JSON data, and safely manages resources with the context manager (with statement). By the end you will be confident reading, writing, and transforming file-based data in Python.","sidebar":"courseSidebar"},"intermediate/index":{"id":"intermediate/index","title":"Intermediate","description":"This section builds on the fundamentals and introduces more powerful Python concepts.","sidebar":"courseSidebar"},"intermediate/inheritance":{"id":"intermediate/inheritance","title":"Inheritance & Dunder Methods","description":"In this module you will learn how Python\'s inheritance system lets classes share and extend behaviour, and how dunder (double-underscore) methods let you integrate your objects seamlessly into the Python language \u2014 making them printable, comparable, and iterable. By the end you will be able to design clean class hierarchies and write Pythonic objects that work naturally with built-in functions and operators.","sidebar":"courseSidebar"},"intro":{"id":"intro","title":"Welcome","description":"Welcome to Python From Zero to Hero \u2014 a comprehensive, hands-on course that takes you from absolute beginner to advanced Python developer.","sidebar":"courseSidebar"}}}}')}}]);